// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');
const loadInter = makeLoadFont('Inter');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();
const { fontFamily: interFamily } = loadInter();



export type TenMinuteTrickProps = Record<string, any>;

const TenMinuteTrick: React.FC<TenMinuteTrickProps> = ({
  backgroundColor = "#070314",
  transparentBackground = true,
  durationInSeconds = 8,
  timerColor = "#00e5ff",
  textColor = "#ffffff",
  textShadowColor = "#00e5ff",
  messageText = "¡Truco de menos de 10 minutos!",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timer bounds
  const endMs = 599999; // 09:59:99
  const timerStopFrame = Math.floor(totalFrames * 0.45);

  // Time calculation
  const currentMs = interpolate(frame, [0, timerStopFrame], [0, endMs], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateRight: "clamp",
  });

  const minutes = Math.floor(currentMs / 60000);
  const seconds = Math.floor((currentMs % 60000) / 1000);
  const centiseconds = Math.floor((currentMs % 1000) / 10);

  const minStr = String(minutes).padStart(2, "0");
  const secStr = String(seconds).padStart(2, "0");
  const csStr = String(centiseconds).padStart(2, "0");
  const timerText = `${minStr}:${secStr}:${csStr}`;

  // Global 3D perspective animations
  const mainRotateX = interpolate(frame, [0, totalFrames], [20, -10]);
  const mainRotateY = interpolate(frame, [0, totalFrames], [-20, 15]);
  const mainScale = interpolate(frame, [0, timerStopFrame, totalFrames], [0.65, 1, 1.05], {
    extrapolateRight: "clamp",
  });

  // Shake effect during acceleration
  const maxShake = Math.min(width, height) * 0.02;
  const shakeIntensity = interpolate(frame, [0, timerStopFrame * 0.5, timerStopFrame], [0, maxShake, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const shakeX = shakeIntensity * (random(`shakeX-${frame}`) - 0.5);
  const shakeY = shakeIntensity * (random(`shakeY-${frame}`) - 0.5);

  // Text pop-in animation synchronized with timer stopping
  const textScale = spring({
    frame: frame - timerStopFrame,
    fps,
    config: { damping: 12, stiffness: 120, mass: 1 },
  });

  const layersCount = 12;

  // Responsive sizing tailored for 9:16 portrait orientation
  const timerFontSize = `${width * 0.18}px`;
  const messageFontSize = `${width * 0.07}px`;
  const maxDim = Math.max(width, height);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        perspective: `${maxDim * 1.2}px`,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Ambient background glow matching the timer color */}
      <svg
        width="100%"
        height="100%"
        style={{ position: "absolute", top: 0, left: 0, pointerEvents: "none" }}
      >
        <defs>
          <radialGradient id="timerGlow" cx="50%" cy="50%" r="60%">
            <stop offset="0%" stopColor={timerColor} stopOpacity={0.15} />
            <stop offset="100%" stopColor={timerColor} stopOpacity={0} />
          </radialGradient>
        </defs>
        <rect width="100%" height="100%" fill="url(#timerGlow)" />
      </svg>

      {/* Main 3D Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transformStyle: "preserve-3d",
          transform: `translate(${shakeX}px, ${shakeY}px) scale(${mainScale}) rotateX(${mainRotateX}deg) rotateY(${mainRotateY}deg)`,
          width: "100%",
          transition: "none",
        }}
      >
        {/* 3D Extruded Digital Clock */}
        <div style={{ position: "relative", transformStyle: "preserve-3d", transition: "none" }}>
          {Array.from({ length: layersCount }).map((_, i) => {
            const isLast = i === layersCount - 1;
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  right: 0,
                  textAlign: "center",
                  transform: `translateZ(${-(i + 1) * 6}px)`,
                  color: "transparent",
                  WebkitTextStroke: `2px ${timerColor}`,
                  opacity: interpolate(i, [0, layersCount - 1], [0.6, 0.05]),
                  filter: isLast ? "blur(8px)" : "none",
                  fontFamily: robotoMonoFamily,
                  fontSize: timerFontSize,
                  fontWeight: 900,
                  lineHeight: 1,
                  fontVariantNumeric: "tabular-nums",
                  whiteSpace: "nowrap",
                  transition: "none",
                }}
              >
                {timerText}
              </div>
            );
          })}
          
          {/* Front Face of the Clock */}
          <div
            style={{
              position: "relative",
              color: timerColor,
              textShadow: `0 0 30px ${timerColor}88`,
              fontFamily: robotoMonoFamily,
              fontSize: timerFontSize,
              fontWeight: 900,
              lineHeight: 1,
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "nowrap",
              transition: "none",
            }}
          >
            {timerText}
          </div>
        </div>

        {/* Floating Message Text Box */}
        <div
          style={{
            marginTop: `${height * 0.06}px`,
            transform: `scale(${textScale}) translateZ(80px)`,
            backgroundColor: `${timerColor}15`,
            border: `2px solid ${timerColor}44`,
            borderRadius: "24px",
            padding: "32px 40px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: `0 10px 30px ${backgroundColor}, inset 0 0 20px ${timerColor}22`,
            width: "85%",
            boxSizing: "border-box",
            transition: "none",
          }}
        >
          <span
            style={{
              color: textColor,
              fontFamily: interFamily,
              fontSize: messageFontSize,
              fontWeight: 800,
              textShadow: `0 4px 16px ${textShadowColor}88`,
              textAlign: "center",
              letterSpacing: "1px",
              lineHeight: 1.3,
              transition: "none",
            }}
          >
            {messageText}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TenMinuteTrick;